package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.kanger.*;

/** Native-only settled baseline to actual pending lease; never publishes or skips family gates. */
final class ContextNativeBaselineMatrix {
    static int checks;
    interface Attempt{void run()throws Exception;}
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
    static ContextNativeCandidateInspection.Limits limits(){return ContextNativeWriterMatrix.limits(64000000);}
    static void positive()throws Exception{
        Path dir=Files.createTempDirectory("native-baseline-trusted-");System.setProperty("user.home",dir.toString());ContextNativeCandidateLeaseMatrix.create(dir,"TR","!@u p(u)->q(u);");ContextNativeCandidateLeaseMatrix.create(dir,"TF","!p(1);");ContextNativeCandidateLeaseMatrix.create(dir,"N","!~r(1);");
        for(boolean reverse:new boolean[]{false,true})try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"X"+reverse)){require(f.mind.compile("!anchor(1);",null,false),"physical baseline anchor");f.db.connectContext(reverse?"TF":"TR","own");f.db.connectContext(reverse?"TR":"TF","own");f.db.connectContext("N");f.db.saveConnections(f.mind);long revision=f.db.getRevision();Set<String> original=ContextNativeCommitGuardMatrix.primary(f);
            ContextNativeWriteBaseline baseline=ContextNativeWriteBaseline.open(f.db,f.mind,1000);require(baseline.foreign.size()==3&&baseline.topology.size()==3&&baseline.x.primary.size()==1,"all ORIGINAL physical members, not one routing proxy or generated cache primary");for(int i=0;i<baseline.foreign.size();i++){ContextProductionInventory view=baseline.foreign.get(i);ContextConnection c=baseline.topology.get(i);require(view.context.equals(c.getTarget().getContextId())&&view.revision==c.getTarget().getRevision()&&view.initialization.equals(c.getInitialization()),"complete original member pin and private view captured");}
            Mind child=new Mind(f.mind);try{require(child.compile("!@u q(u)->r(u);",null,false),"actual prepared native child");ContextPendingProductionSnapshotSession lease=baseline.bind(child);require(lease==baseline.bind(child),"same exact child returns same live lease");ContextNativeBranchInspection.Result refuted=lease.inspectNative(limits());require(refuted.status==ContextNativeBranchInspection.Status.REFUTED&&!refuted.oppositions.isEmpty(),refuted.phase+": "+refuted.reason);require(refuted.foreign.size()==2&&refuted.foreign.stream().anyMatch(c->"own".equals(c.trustedGroup)&&c.members.size()==2),"logical shared cut preserves BOTH physical trusted members");for(ContextNativeBranchInspection.Opposition o:refuted.oppositions){require(o.sources.size()==4&&o.sources.stream().filter(s->!s.localX).map(s->s.context).distinct().count()==3,"actual pending X plus both trusted originals and independent negative Sources");for(org.kanger.ContextProductionCapture.Source s:o.sources)if(!s.localX)require(baseline.foreign.stream().anyMatch(v->v.context.equals(s.context)&&v.revision==s.revision&&s.view.equals("inventory:"+v.fingerprint)),"proof binds baseline original physical pin/view");}baseline.requireCurrent();require(true,"baseline and owning pending lease both current after actual native inspection");baseline.close();reject(()->lease.inspectNative(limits()),"closing baseline closes owned pending lease");}finally{baseline.close();f.mind.release(child);}
            ContextNativeWriteBaseline initialized=ContextNativeWriteBaseline.open(f.db,f.mind,1000);f.db.applyConnectionCommand(f.mind,"TF","-p(1);");f.db.applyConnectionCommand(f.mind,"TF","!p(2);");reject(initialized::requireCurrent,"private initialization invalidates prior baseline");initialized.close();
            try(ContextNativeWriteBaseline fresh=ContextNativeWriteBaseline.open(f.db,f.mind,1000)){require(fresh.foreign.stream().anyMatch(v->v.initialization.size()==2),"fresh trusted member baseline retains complete private commands");Mind safe=new Mind(f.mind);try{require(safe.compile("!@u q(u)->r(u);",null,false),"prepared child over initialized trusted member");ContextNativeBranchInspection.Result r=fresh.bind(safe).inspectNative(limits());require(r.status==ContextNativeBranchInspection.Status.STABLE_SUPPLIED,"fresh initialized trusted supplied scope is stable, not writer admission");fresh.requireCurrent();}finally{f.mind.release(safe);}}
            ContextNativeWriteBaseline old=ContextNativeWriteBaseline.open(f.db,f.mind,1000);CommuneRuntime cached=f.db.productionExecutionTopology().stream().filter(c->c.commune()!=null).findFirst().get().commune();f.db.connectContext("TR","own");require(cached==f.db.productionExecutionTopology().stream().filter(c->c.commune()!=null).findFirst().get().commune(),"qualified shared cache legitimately reuses equivalent original member knowledge");reject(old::requireCurrent,"raw connection instance replacement invalidates old baseline despite cache reuse");old.close();try(ContextNativeWriteBaseline fresh=ContextNativeWriteBaseline.open(f.db,f.mind,1000)){fresh.requireCurrent();require(true,"fresh complete manifest accepts legitimate cached runtime reuse");}
            require(f.db.getRevision()==revision&&ContextNativeCommitGuardMatrix.primary(f).equals(original),"baseline/inspection/private member edits never publish physical X");reject(()->f.db.writeNativeProductionCandidate(f.mind,"!notActivated(7);",limits(),64000000,64000000,1000000,false),"standalone writer TRUST activation remains separately gated");require(f.db.getRevision()==revision&&ContextNativeCommitGuardMatrix.primary(f).equals(original),"no writer effect from baseline support alone");
        }
        System.out.println("NATIVE_BASELINE_TRUSTED orders=2 allOriginalMembers=true actualPendingSources=true initializedViews=true qualifiedCacheReuse=true noAdmission=true noPublication=true");
    }
    static void ownership()throws Exception{
        Path dir=Files.createTempDirectory("native-baseline-owner-");System.setProperty("user.home",dir.toString());ContextNativeCandidateLeaseMatrix.create(dir,"A","!a(1);");long revision;
        try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"X")){require(f.mind.compile("!anchor(1);",null,false),"owning baseline parent");f.db.connectContext("A");f.db.saveConnections(f.mind);revision=f.db.getRevision();reject(()->ContextNativeWriteBaseline.open(f.db,f.mind,1),"whole member row limit refuses, no prefix baseline");ContextNativeWriteBaseline closed=ContextNativeWriteBaseline.open(f.db,f.mind,1000);closed.close();reject(closed::requireCurrent,"closed baseline cannot be reused");
            try(ContextNativeWriteBaseline b=ContextNativeWriteBaseline.open(f.db,f.mind,1000)){AtomicBoolean refused=new AtomicBoolean();Thread t=new Thread(()->{try{b.requireCurrent();}catch(Exception expected){refused.set(true);}});t.start();t.join();require(refused.get(),"baseline thread confinement");b.requireCurrent();Mind offline=new Mind(f.user);f.user.setCurrentMind(offline);try{reject(b::requireCurrent,"active source identity changed");}finally{f.user.setCurrentMind(f.mind);}b.requireCurrent();}
            Mind first=new Mind(f.mind);try{reject(()->ContextNativeWriteBaseline.open(f.db,f.mind,1000),"baseline cannot start after pending root reservation");}finally{f.mind.release(first);}
            try(ContextNativeWriteBaseline b=ContextNativeWriteBaseline.open(f.db,f.mind,1000)){Mind a=new Mind(f.mind),other=new Mind(f.mind);try{reject(()->b.bind(a),"multiple actual root reservations refuse binding");}finally{f.mind.release(other);}reject(()->b.bind(a),"failed baseline cannot be retried after reservation repair");f.mind.release(a);}
            try(ContextNativeWriteBaseline b=ContextNativeWriteBaseline.open(f.db,f.mind,1000)){Mind child=new Mind(f.mind);try{require(child.compile("!prepared(1);",null,false),"prepared ownership fixture");ContextPendingProductionSnapshotSession lease=b.bind(child);require(child.compile("!changed(2);",null,false),"actual bound child mutation");reject(b::requireCurrent,"bound child change invalidates owning baseline");reject(()->b.bind(child),"changed child cannot reuse baseline binding");reject(lease::requireCurrent,"old returned lease also refuses changed child");}finally{f.mind.release(child);}}
            try(ContextNativeWriteBaseline b=ContextNativeWriteBaseline.open(f.db,f.mind,1000)){f.db.disconnectContext("A");reject(b::requireCurrent,"topology member removal invalidates baseline");}f.db.connectContext("A");
            try(ContextNativeWriteBaseline b=ContextNativeWriteBaseline.open(f.db,f.mind,1000)){require(f.mind.compile("!parentChanged(3);",null,false),"actual parent knowledge mutation");reject(b::requireCurrent,"parent inventory mutation invalidates settled baseline");}
            reject(()->ContextNativeWriteBaseline.open(f.db,new Mind(new User()),1000),"unrelated caller/provider cannot capture baseline");
        }
        try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"X@"+revision)){require(f.db.isReadOnly(),"historical owning baseline fixture");reject(()->ContextNativeWriteBaseline.open(f.db,f.mind,1000),"historical read-only provider has no writable baseline");}
        System.out.println("NATIVE_BASELINE_OWNERSHIP closedThreadOwnerRows=true settledAndExactChild=true failedBindingPoisoned=true parentChildTopologyFreshness=true historicalRefused=true");
    }
}
